-- ============================================================
-- 10_esquema.sql — las 7 tablas, port de MySQL a Postgres.
-- Plantilla: {{esquema}} se reemplaza por el nombre de la
-- colección (anfibios, aves). La lee nube/db/migrar.py.
--
-- Fuente: SHOW CREATE TABLE de biodiversidad_panama, guardado
-- en nube/db/inventario_mysql/anfibios.sql.
--
-- Equivalencias de tipos:
--   int AUTO_INCREMENT   -> integer GENERATED BY DEFAULT AS IDENTITY
--   tinyint              -> smallint (Postgres no tiene tinyint)
--   decimal(9,6)         -> numeric(9,6)
--   varchar utf8mb4_unicode_ci -> varchar COLLATE public.es_ci_ai
-- Los índices que MySQL crea solo para las llaves foráneas
-- (KEY fk_*) se llaman idx_* aquí: en Postgres el índice y la
-- restricción no comparten nombre.
-- ============================================================

DROP SCHEMA IF EXISTS {{esquema}} CASCADE;
CREATE SCHEMA {{esquema}};

CREATE TABLE {{esquema}}.orden (
    orden_id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre   varchar(50) COLLATE public.es_ci_ai NOT NULL,
    CONSTRAINT orden_pkey PRIMARY KEY (orden_id),
    CONSTRAINT uq_orden_nombre UNIQUE (nombre)
);

CREATE TABLE {{esquema}}.familia (
    familia_id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre     varchar(50) COLLATE public.es_ci_ai NOT NULL,
    orden_id   integer NOT NULL,
    CONSTRAINT familia_pkey PRIMARY KEY (familia_id),
    CONSTRAINT uq_familia_nombre UNIQUE (nombre),
    CONSTRAINT fk_familia_orden FOREIGN KEY (orden_id)
        REFERENCES {{esquema}}.orden (orden_id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_familia_orden ON {{esquema}}.familia (orden_id);

CREATE TABLE {{esquema}}.provincia (
    provincia_id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre       varchar(50) COLLATE public.es_ci_ai NOT NULL,
    CONSTRAINT provincia_pkey PRIMARY KEY (provincia_id),
    CONSTRAINT uq_provincia_nombre UNIQUE (nombre)
);

CREATE TABLE {{esquema}}.fuente (
    fuente_id   integer GENERATED BY DEFAULT AS IDENTITY,
    nombre      varchar(100) COLLATE public.es_ci_ai NOT NULL,
    url         varchar(255) COLLATE public.es_ci_ai,
    licencia    varchar(30)  COLLATE public.es_ci_ai,
    descripcion varchar(255) COLLATE public.es_ci_ai,
    CONSTRAINT fuente_pkey PRIMARY KEY (fuente_id),
    CONSTRAINT uq_fuente_nombre UNIQUE (nombre)
);

CREATE TABLE {{esquema}}.observador (
    observador_id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre        varchar(100) COLLATE public.es_ci_ai NOT NULL,
    CONSTRAINT observador_pkey PRIMARY KEY (observador_id)
);
CREATE INDEX idx_observador_nombre ON {{esquema}}.observador (nombre);

CREATE TABLE {{esquema}}.especie (
    especie_id        integer GENERATED BY DEFAULT AS IDENTITY,
    nombre_cientifico varchar(150) COLLATE public.es_ci_ai NOT NULL,
    nombre_comun      varchar(100) COLLATE public.es_ci_ai,
    genero            varchar(50)  COLLATE public.es_ci_ai NOT NULL,
    familia_id        integer NOT NULL,
    CONSTRAINT especie_pkey PRIMARY KEY (especie_id),
    CONSTRAINT uq_especie_nombre_cientifico UNIQUE (nombre_cientifico),
    CONSTRAINT fk_especie_familia FOREIGN KEY (familia_id)
        REFERENCES {{esquema}}.familia (familia_id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_especie_familia ON {{esquema}}.especie (familia_id);

CREATE TABLE {{esquema}}.avistamiento (
    avistamiento_id integer GENERATED BY DEFAULT AS IDENTITY,
    gbif_id         bigint NOT NULL,
    especie_id      integer NOT NULL,
    provincia_id    integer NOT NULL,
    observador_id   integer NOT NULL,
    fuente_id       integer NOT NULL,
    latitud         numeric(9,6) NOT NULL,
    longitud        numeric(9,6) NOT NULL,
    fecha           date NOT NULL,
    mes             smallint NOT NULL,
    anio            smallint NOT NULL,
    licencia        varchar(20)  COLLATE public.es_ci_ai NOT NULL,
    occurrence_url  varchar(100) COLLATE public.es_ci_ai,
    media_type      varchar(20)  COLLATE public.es_ci_ai,
    CONSTRAINT avistamiento_pkey PRIMARY KEY (avistamiento_id),
    CONSTRAINT uq_avistamiento_gbif_id UNIQUE (gbif_id),
    CONSTRAINT fk_avist_especie FOREIGN KEY (especie_id)
        REFERENCES {{esquema}}.especie (especie_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_avist_fuente FOREIGN KEY (fuente_id)
        REFERENCES {{esquema}}.fuente (fuente_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_avist_observador FOREIGN KEY (observador_id)
        REFERENCES {{esquema}}.observador (observador_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_avist_provincia FOREIGN KEY (provincia_id)
        REFERENCES {{esquema}}.provincia (provincia_id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT chk_anio CHECK (anio BETWEEN 2000 AND 2100),
    CONSTRAINT chk_latitud CHECK (latitud BETWEEN -90 AND 90),
    CONSTRAINT chk_licencia CHECK (licencia IN ('CC_BY_NC_4_0', 'CC_BY_4_0', 'CC0_1_0')),
    CONSTRAINT chk_longitud CHECK (longitud BETWEEN -180 AND 180),
    CONSTRAINT chk_media_type CHECK (media_type IN ('StillImage', 'Sound', 'StillImage;Sound') OR media_type IS NULL),
    CONSTRAINT chk_mes CHECK (mes BETWEEN 1 AND 12)
);
CREATE INDEX idx_avist_observador ON {{esquema}}.avistamiento (observador_id);
CREATE INDEX idx_avist_fuente     ON {{esquema}}.avistamiento (fuente_id);
CREATE INDEX idx_avist_especie    ON {{esquema}}.avistamiento (especie_id);
CREATE INDEX idx_avist_provincia  ON {{esquema}}.avistamiento (provincia_id);
CREATE INDEX idx_avist_anio_mes   ON {{esquema}}.avistamiento (anio, mes);
CREATE INDEX idx_avist_media      ON {{esquema}}.avistamiento (media_type);
